<?php

declare(strict_types=1);

namespace App\Repositories;

use App\Database\Connection;use App\Security\Security;use App\Services\Cms\CmsRepositoryInterface;use DateTimeImmutable;use DomainException;use PDO;use PDOException;
final class CmsRepository extends Repository implements CmsRepositoryInterface
{
 public function __construct(Connection$db){parent::__construct($db);}public function publicPosts(string$type):array{$s=$this->connection()->prepare("SELECT public_id,title,slug,excerpt,meta_title,meta_description,published_at FROM posts WHERE post_type=:type AND status='published' AND published_at<=CURRENT_TIMESTAMP(6) ORDER BY published_at DESC,id DESC");$s->execute(['type'=>$type]);return$s->fetchAll();}public function publicPost(string$type,string$slug):?array{$s=$this->connection()->prepare("SELECT public_id,post_type,title,slug,excerpt,body_html,meta_title,meta_description,published_at FROM posts WHERE post_type=:type AND slug=:slug AND status='published' AND published_at<=CURRENT_TIMESTAMP(6) LIMIT 1");$s->execute(['type'=>$type,'slug'=>$slug]);$r=$s->fetch();return is_array($r)?$r:null;}public function publicPage(string$slug):?array{$s=$this->connection()->prepare("SELECT public_id,title,slug,summary,body_html,meta_title,meta_description,published_at FROM pages WHERE slug=:slug AND status='published' AND published_at<=CURRENT_TIMESTAMP(6) LIMIT 1");$s->execute(['slug'=>$slug]);$r=$s->fetch();return is_array($r)?$r:null;}
 public function publicLibrary():array{$db=$this->connection();return['resources'=>$this->publicPosts('resource'),'downloads'=>$db->query("SELECT downloads.public_id,downloads.title,downloads.slug,downloads.description,downloads.download_count,downloads.published_at,media.original_name,media.mime_type,media.size_bytes FROM downloads INNER JOIN media ON media.id=downloads.media_id AND media.status='published' WHERE downloads.status='published' AND downloads.published_at<=CURRENT_TIMESTAMP(6) ORDER BY downloads.published_at DESC,downloads.id DESC")->fetchAll(),'faqs'=>$db->query("SELECT public_id,question,answer_text FROM faqs WHERE status='published' AND published_at<=CURRENT_TIMESTAMP(6) ORDER BY display_order,id")->fetchAll()];}
 public function publicMedia(string$id):?array{$s=$this->connection()->prepare("SELECT public_id,original_name,storage_path,mime_type,size_bytes,sha256,alt_text FROM media WHERE public_id=:id AND status='published' LIMIT 1");$s->execute(['id'=>$id]);$r=$s->fetch();return is_array($r)?$r:null;}public function publicDownload(string$slug,DateTimeImmutable$now):?array{return$this->database->transaction(function(PDO$db)use($slug):?array{$s=$db->prepare("SELECT downloads.id,downloads.title,media.public_id,media.original_name,media.storage_path,media.mime_type,media.size_bytes,media.sha256 FROM downloads INNER JOIN media ON media.id=downloads.media_id AND media.status='published' WHERE downloads.slug=:slug AND downloads.status='published' AND downloads.published_at<=CURRENT_TIMESTAMP(6) LIMIT 1 FOR UPDATE");$s->execute(['slug'=>$slug]);$r=$s->fetch();if(!is_array($r))return null;$db->prepare('UPDATE downloads SET download_count=download_count+1 WHERE id=:id')->execute(['id'=>$r['id']]);unset($r['id']);return$r;});}
 public function adminDashboard():array{$db=$this->connection();return['pages'=>$db->query('SELECT public_id,title,slug,status,updated_at FROM pages ORDER BY updated_at DESC')->fetchAll(),'posts'=>$db->query('SELECT public_id,post_type,title,slug,status,updated_at FROM posts ORDER BY updated_at DESC')->fetchAll(),'media'=>$db->query('SELECT public_id,original_name,mime_type,size_bytes,alt_text,status,created_at FROM media ORDER BY created_at DESC')->fetchAll(),'faqs'=>$db->query('SELECT public_id,question,display_order,status FROM faqs ORDER BY display_order,id')->fetchAll(),'downloads'=>$db->query('SELECT downloads.public_id,downloads.title,downloads.slug,downloads.status,media.original_name FROM downloads INNER JOIN media ON media.id=downloads.media_id ORDER BY downloads.updated_at DESC')->fetchAll()];}
 public function savePage(int$a,?string$id,array$d,DateTimeImmutable$n):string{return$this->saveContent('pages',$a,$id,$d,$n);}public function savePost(int$a,?string$id,array$d,DateTimeImmutable$n):string{return$this->saveContent('posts',$a,$id,$d,$n);}private function saveContent(string$table,int$actor,?string$id,array$d,DateTimeImmutable$now):string{try{return$this->database->transaction(function(PDO$db)use($table,$actor,$id,$d,$now):string{$created=$id===null;$id??=Security::uuidV4();$slug=$this->uniqueSlug($db,$table,$d['slug'],$id,$table==='posts'?$d['post_type']:null);$published=$d['status']==='published'?$this->stamp($now):null;$base=['public_id'=>$id,'title'=>$d['title'],'slug'=>$slug,'body'=>$d['body_html'],'meta_title'=>$d['meta_title'],'meta_description'=>$d['meta_description'],'status'=>$d['status'],'published'=>$published,'actor'=>$actor,'now'=>$this->stamp($now)];if($created){$base['actor_updated']=$actor;$base['created_at']=$this->stamp($now);}if($table==='pages'){$base['summary']=$d['summary'];$sql=$created?"INSERT INTO pages (public_id,title,slug,summary,body_html,meta_title,meta_description,status,published_at,created_by_user_id,updated_by_user_id,created_at,updated_at) VALUES (:public_id,:title,:slug,:summary,:body,:meta_title,:meta_description,:status,:published,:actor,:actor_updated,:created_at,:now)":"UPDATE pages SET title=:title,slug=:slug,summary=:summary,body_html=:body,meta_title=:meta_title,meta_description=:meta_description,status=:status,published_at=:published,updated_by_user_id=:actor,updated_at=:now WHERE public_id=:public_id";}else{$base['type']=$d['post_type'];$base['excerpt']=$d['excerpt'];$sql=$created?"INSERT INTO posts (public_id,post_type,title,slug,excerpt,body_html,meta_title,meta_description,status,published_at,created_by_user_id,updated_by_user_id,created_at,updated_at) VALUES (:public_id,:type,:title,:slug,:excerpt,:body,:meta_title,:meta_description,:status,:published,:actor,:actor_updated,:created_at,:now)":"UPDATE posts SET post_type=:type,title=:title,slug=:slug,excerpt=:excerpt,body_html=:body,meta_title=:meta_title,meta_description=:meta_description,status=:status,published_at=:published,updated_by_user_id=:actor,updated_at=:now WHERE public_id=:public_id";}$s=$db->prepare($sql);$s->execute($base);if(!$created&&$s->rowCount()===0)$this->ensureExists($db,$table,$id);$this->audit($db,$actor,'cms.'.rtrim($table,'s').($created?'_created':'_updated'),rtrim($table,'s'),$id,['status'=>$d['status'],'slug'=>$slug],$now);return$id;});}catch(PDOException$e){if($e->getCode()==='23000')throw new DomainException('Content slug conflicts with an existing record.');throw$e;}}
 public function saveFaq(int$a,?string$id,array$d,DateTimeImmutable$n):string{return$this->database->transaction(function(PDO$db)use($a,$id,$d,$n):string{$created=$id===null;$id??=Security::uuidV4();$published=$d['status']==='published'?$this->stamp($n):null;$values=['id'=>$id,'question'=>$d['question'],'answer'=>$d['answer_text'],'order'=>$d['display_order'],'status'=>$d['status'],'published'=>$published,'actor'=>$a,'now'=>$this->stamp($n)];if($created){$values['actor_updated']=$a;$values['created_at']=$this->stamp($n);}$sql=$created?'INSERT INTO faqs (public_id,question,answer_text,display_order,status,published_at,created_by_user_id,updated_by_user_id,created_at,updated_at) VALUES (:id,:question,:answer,:order,:status,:published,:actor,:actor_updated,:created_at,:now)':'UPDATE faqs SET question=:question,answer_text=:answer,display_order=:order,status=:status,published_at=:published,updated_by_user_id=:actor,updated_at=:now WHERE public_id=:id';$s=$db->prepare($sql);$s->execute($values);if(!$created&&$s->rowCount()===0)$this->ensureExists($db,'faqs',$id);$this->audit($db,$a,'cms.faq_'.($created?'created':'updated'),'faq',$id,['status'=>$d['status']],$n);return$id;});}
 public function createMedia(int$a,array$d,DateTimeImmutable$n):string{try{return$this->database->transaction(function(PDO$db)use($a,$d,$n):string{$id=Security::uuidV4();$db->prepare("INSERT INTO media (public_id,original_name,storage_path,mime_type,size_bytes,sha256,alt_text,status,uploaded_by_user_id,created_at,updated_at) VALUES (:id,:name,:path,:mime,:size,:hash,:alt,'draft',:actor,:created_at,:updated_at)")->execute(['id'=>$id,'name'=>$d['original_name'],'path'=>$d['storage_path'],'mime'=>$d['mime_type'],'size'=>$d['size_bytes'],'hash'=>$d['sha256'],'alt'=>$d['alt_text'],'actor'=>$a,'created_at'=>$this->stamp($n),'updated_at'=>$this->stamp($n)]);$this->audit($db,$a,'cms.media_uploaded','media',$id,['mime_type'=>$d['mime_type'],'size_bytes'=>$d['size_bytes'],'sha256'=>$d['sha256']],$n);return$id;});}catch(PDOException$e){throw new DomainException('Media metadata could not be saved.');}}
 public function updateMediaStatus(int$a,string$id,string$status,DateTimeImmutable$n):void{$this->database->transaction(function(PDO$db)use($a,$id,$status,$n):void{$s=$db->prepare('SELECT id,status FROM media WHERE public_id=:id LIMIT 1 FOR UPDATE');$s->execute(['id'=>$id]);$m=$s->fetch();if(!is_array($m))throw new DomainException('Media not found.');if($status==='archived'){$used=$db->prepare("SELECT COUNT(*) FROM downloads WHERE media_id=:id AND status='published'");$used->execute(['id'=>$m['id']]);if((int)$used->fetchColumn()>0)throw new DomainException('Media used by a published download cannot be archived.');}$db->prepare('UPDATE media SET status=:status,updated_at=:now WHERE id=:id')->execute(['status'=>$status,'now'=>$this->stamp($n),'id'=>$m['id']]);$this->audit($db,$a,'cms.media_status_updated','media',$id,['from_status'=>$m['status'],'to_status'=>$status],$n);});}
 public function saveDownload(int$a,?string$id,array$d,DateTimeImmutable$n):string{return$this->database->transaction(function(PDO$db)use($a,$id,$d,$n):string{$media=$db->prepare("SELECT id FROM media WHERE public_id=:id AND status<>'archived' LIMIT 1 FOR UPDATE");$media->execute(['id'=>$d['media']]);$mediaId=$media->fetchColumn();if($mediaId===false)throw new DomainException('Selected media is unavailable.');$created=$id===null;$id??=Security::uuidV4();$slug=$this->uniqueSlug($db,'downloads',$d['slug'],$id);$published=$d['status']==='published'?$this->stamp($n):null;$values=['id'=>$id,'title'=>$d['title'],'slug'=>$slug,'description'=>$d['description'],'media'=>$mediaId,'status'=>$d['status'],'published'=>$published,'actor'=>$a,'now'=>$this->stamp($n)];if($created){$values['actor_updated']=$a;$values['created_at']=$this->stamp($n);}$sql=$created?'INSERT INTO downloads (public_id,title,slug,description,media_id,status,published_at,created_by_user_id,updated_by_user_id,created_at,updated_at) VALUES (:id,:title,:slug,:description,:media,:status,:published,:actor,:actor_updated,:created_at,:now)':'UPDATE downloads SET title=:title,slug=:slug,description=:description,media_id=:media,status=:status,published_at=:published,updated_by_user_id=:actor,updated_at=:now WHERE public_id=:id';$s=$db->prepare($sql);$s->execute($values);if(!$created&&$s->rowCount()===0)$this->ensureExists($db,'downloads',$id);if($d['status']==='published')$db->prepare("UPDATE media SET status='published',updated_at=:now WHERE id=:id AND status='draft'")->execute(['now'=>$this->stamp($n),'id'=>$mediaId]);$this->audit($db,$a,'cms.download_'.($created?'created':'updated'),'download',$id,['status'=>$d['status'],'slug'=>$slug],$n);return$id;});}
 private function uniqueSlug(PDO$db,string$table,string$base,string$id,?string$type=null):string{$candidate=$base;$i=2;do{$sql="SELECT id FROM {$table} WHERE slug=:slug AND public_id<>:id".($type!==null?' AND post_type=:type':'').' LIMIT 1';$s=$db->prepare($sql);$params=['slug'=>$candidate,'id'=>$id];if($type!==null)$params['type']=$type;$s->execute($params);if($s->fetchColumn()===false)return$candidate;$suffix='-'.$i++;$candidate=substr($base,0,200-strlen($suffix)).$suffix;}while($i<1000);throw new DomainException('A unique slug could not be generated.');}private function ensureExists(PDO$db,string$table,string$id):void{$s=$db->prepare("SELECT id FROM {$table} WHERE public_id=:id");$s->execute(['id'=>$id]);if($s->fetchColumn()===false)throw new DomainException('Content record not found.');}private function audit(PDO$db,int$a,string$action,string$type,string$id,array$v,DateTimeImmutable$n):void{$db->prepare("INSERT INTO audit_logs (actor_user_id,action,auditable_type,auditable_id,description,new_values,request_id,created_at) VALUES (:actor,:action,:type,:id,'A CMS content action was completed.',:values,:request,:now)")->execute(['actor'=>$a,'action'=>$action,'type'=>$type,'id'=>$id,'values'=>json_encode($v,JSON_THROW_ON_ERROR),'request'=>bin2hex(random_bytes(16)),'now'=>$this->stamp($n)]);}private function stamp(DateTimeImmutable$d):string{return$d->format('Y-m-d H:i:s.u');}
}
